mapper.select:
		SELECT MSG_ID,MSG_BODY,CREATED_BY_NAME,TO_CHAR(EFFECTIVE_START_DATE, 'MM/DD/YYYY HH:MI:SS AM') EFFECTIVE_START_DATE,
            TO_CHAR(EFFECTIVE_END_DATE, 'MM/DD/YYYY HH:MI:SS AM') EFFECTIVE_END_DATE, FLAG_DELETED, TO_CHAR(LAST_UPDATED_DATE, 'MM/DD/YYYY HH:MI:SS AM') LAST_UPDATED_DATE,LAST_UPDATED_BY_NAME, LAST_UPDATED_SHORT_NAME, CREATED_BY_SHORT_NAME
            FROM NYEHMS_SYSTEM_MSG_HISTORY_VW  where MSG_ID = #{messageId}
